mapper.select:
SELECT c.contest_id
FROM contest_rank_snapshot s
INNER JOIN contest c ON c.contest_id = s.contest_id
WHERE c.type = 0 AND c.del_flag = 0 AND c.end_time <= #{now}
  AND (
      (s.state IN ('WAITING', 'ERROR') AND s.next_build_at <= #{now})
      OR (s.state = 'BUILDING' AND (s.lease_until IS NULL OR s.lease_until <= #{now}))
  )
ORDER BY c.end_time ASC, c.contest_id ASC
LIMIT #{limit}

mapper.update:
UPDATE contest_rank_snapshot
SET state = 'WAITING', next_build_at = #{now}, lease_owner = NULL, lease_until = NULL,
    updated_at = #{now}
WHERE contest_id = #{contestId}
  AND (state <> 'BUILDING' OR lease_until IS NULL OR lease_until <= #{now})

UPDATE contest_rank_snapshot
SET state = 'WAITING', pending_count = #{pendingCount}, next_build_at = #{nextBuildAt},
    lease_owner = NULL, lease_until = NULL, last_error = #{lastError}, updated_at = #{now}
WHERE contest_id = #{contestId}

UPDATE contest_rank_snapshot
SET state = 'ERROR', build_attempts = #{buildAttempts}, next_build_at = #{nextBuildAt},
    pending_count = #{pendingCount}, lease_owner = NULL, lease_until = NULL,
    last_error = #{lastError}, updated_at = #{now}
WHERE contest_id = #{contestId}

UPDATE contest_rank_snapshot
SET state = 'BUILDING', next_version = #{candidateVersion},
    pending_count = #{pendingCount}, lease_owner = #{leaseOwner}, lease_until = #{leaseUntil},
    last_error = NULL, updated_at = #{now}
WHERE contest_id = #{contestId}
  AND (
      (state IN ('WAITING', 'ERROR') AND next_build_at <= #{now})
      OR (state = 'BUILDING' AND (lease_until IS NULL OR lease_until <= #{now}))
  )

UPDATE contest_rank_snapshot
SET lease_until = #{leaseUntil}, updated_at = #{now}
WHERE contest_id = #{contestId} AND state = 'BUILDING'
  AND next_version = #{candidateVersion} AND lease_owner = #{leaseOwner}
  AND lease_until > #{now}

UPDATE contest_rank_snapshot
SET state = 'READY', version = #{candidateVersion}, source_seq = #{sourceSeq},
    source_mode = #{sourceMode}, rule_version = #{ruleVersion}, total_users = #{totalUsers},
    pending_count = 0, build_attempts = 0, lease_owner = NULL, lease_until = NULL,
    generated_at = #{generatedAt}, next_build_at = #{generatedAt}, last_error = NULL,
    updated_at = #{generatedAt}
WHERE contest_id = #{contestId} AND state = 'BUILDING'
  AND next_version = #{candidateVersion} AND lease_owner = #{leaseOwner}
  AND lease_until > #{generatedAt}

UPDATE contest_rank_snapshot
SET state = 'ERROR', build_attempts = #{buildAttempts}, next_build_at = #{nextBuildAt},
    pending_count = #{pendingCount}, lease_owner = NULL, lease_until = NULL,
    last_error = #{lastError}, updated_at = #{now}
WHERE contest_id = #{contestId} AND state = 'BUILDING'
  AND next_version = #{candidateVersion} AND lease_owner = #{leaseOwner}
  AND lease_until > #{now}
